import"./app-B3HrrAoI.js";/* empty css                  */const l=new URLSearchParams(window.location.search),a=l.get("id");async function m(i){try{const o=await fetch(`/api/users/${i}`);if(!o.ok)throw new Error("User not found");const t=await o.json();document.getElementById("profile-name").textContent=t.name,document.getElementById("profile-bio").textContent=t.bio||"This user has no bio.",document.getElementById("profile-date").textContent=`Joined: ${new Date(t.createdAt).toDateString()}`;const r="https://i.postimg.cc/KvF0rh0Q/custom-default-avatar.png",c=t.profilePhoto?.trim()||r;document.getElementById("profile-photo").src=c,document.getElementById("user-name-label").textContent=t.name;const n=await fetch(`/api/posts?authorId=${t._id}&limit=1000`);if(!n.ok)throw new Error("Failed to fetch user's posts");const{posts:s}=await n.json();document.getElementById("posts-list").innerHTML=s.length?s.map(e=>`
            <div class="post-card" data-slug="${e.slug}">
                <h3>${e.title}</h3>
                <p>${e.content.substring(0,120)+"..."}</p>
            </div>
            `).join(""):"<p class='no-posts'>No posts available.</p>",document.querySelectorAll(".post-card").forEach(e=>{e?.addEventListener("click",()=>{const d=e.dataset.slug;window.location.href=`post.html?slug=${d}`})})}catch(o){document.body.innerHTML=`<p>${o.message}</p>`}}a?m(a):document.body.innerHTML="<h2>User not specified</h2>";
